<script lang="ts">
  import type { HTMLButtonAttributes } from 'svelte/elements'; import { onMount } from 'svelte'; import { Moon, Sun } from '@lucide/svelte'; import { cn } from '../../internal/cn.js'; import type { Size, Variant } from '../../types.js';
  type Props=HTMLButtonAttributes&{storageKey?:string;lightTheme?:string;darkTheme?:string;size?:Size;variant?:Variant}; let {storageKey='rg-theme',lightTheme='robin',darkTheme='robin-dark',size='sm',variant='outline',class:className,...rest}:Props=$props(); let dark=$state(false); let mounted=$state(false);
  function apply(next:boolean){dark=next;document.documentElement.dataset.theme=next?darkTheme:lightTheme;try{localStorage.setItem(storageKey,next?'dark':'light')}catch{}}
  onMount(()=>{let saved:string|null=null;try{saved=localStorage.getItem(storageKey)}catch{}const current=document.documentElement.dataset.theme;apply(saved?saved==='dark':current===darkTheme||(current!==lightTheme&&matchMedia('(prefers-color-scheme: dark)').matches));mounted=true});
</script>
<button {...rest} type="button" class={cn('rg-button rg-icon-button rg-theme-toggle',className)} data-variant={variant} data-size={size} aria-label={mounted ? (dark?'Helles Design aktivieren':'Dunkles Design aktivieren') : 'Design umschalten'} aria-pressed={mounted ? dark : undefined} onclick={()=>apply(!dark)}><span class="rg-theme-toggle-icon rg-theme-toggle-icon-moon" aria-hidden="true"><Moon size={17}/></span><span class="rg-theme-toggle-icon rg-theme-toggle-icon-sun" aria-hidden="true"><Sun size={17}/></span></button>
